function matrixMarkup(name,rows,cols){let s="<div class='matrix-wrap'><div class='matrix-controls'><strong>"+name+"</strong><span class='helper-text'>"+rows+" × "+cols+"</span></div><div class='matrix-grid-wrap'><div class='matrix-box' style='grid-template-columns:repeat("+cols+",48px)'>";for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)s+="<input class='text-input matrix-cell' type='number' step='any' data-matrix='"+name+"' data-r='"+r+"' data-c='"+c+"' data-save='matrix-"+name+"-"+r+"-"+c+"' value='"+(name==="A"?(r===c?1:0):(r===c?2:1))+"'>";return s+"</div></div></div>"}
function readMatrix(root,name){let cells=$$("[data-matrix='"+name+"']",root),nR=Math.max.apply(null,cells.map(function(x){return Number(x.dataset.r)}))+1,nC=Math.max.apply(null,cells.map(function(x){return Number(x.dataset.c)}))+1,out=Array.from({length:nR},function(){return Array(nC).fill(0)});cells.forEach(function(x){let v=Number(x.value);if(x.value.trim()===""||!Number.isFinite(v))throw Error("Enter finite numbers in every matrix cell.");out[Number(x.dataset.r)][Number(x.dataset.c)]=v});return out}
